    your_rank: "La tua posizione: {n}",
    blocked_none: "Non hai bloccato nessuno.",
    ed_script_help_lua: "Lua in stile Roblox (isolato): Instance.new(\"Part\"), workspace, game:GetService(\"Players\" / \"TweenService\" / \"RunService\" / \"UserInputService\" / \"Lighting\" / \"Debris\" / \"CollectionService\"), task.wait / task.spawn, eventi con :Connect, Touched, ClickDetector, ProximityPrompt, ScreenGui / TextLabel / TextButton, leaderstats. Funzionano anche on(\"join\"), command(\"name\", fn), game.say... 1 stud = 1 blocco.",
    ed_api_title: "Riferimento API (Roblox)",
    ed_api: "<p><b>Supportato</b>: Instance.new / Clone / Destroy / FindFirstChild / WaitForChild / GetChildren / SetAttribute; Part (Position, Size, Color, Material, Shape, Transparency, Anchored, CanCollide, CFrame, Touched), PointLight, ClickDetector.MouseClick, ProximityPrompt.Triggered, SpawnLocation, Model:MoveTo; Players (LocalPlayer, PlayerAdded, CharacterAdded, Chatted, leaderstats), Humanoid (WalkSpeed, JumpPower, Health, Died); Workspace.Gravity; Lighting.ClockTime; TweenService:Create + TweenInfo + Enum.EasingStyle; RunService.Heartbeat / RenderStepped; UserInputService.InputBegan / IsKeyDown; ContextActionService:BindAction; Debris:AddItem; CollectionService; HttpService:JSONEncode / JSONDecode / GenerateGUID; BindableEvent; RemoteEvent (locale); oggetti Value; ScreenGui, Frame, TextLabel, TextButton, UICorner, UIStroke, UIListLayout, UIPadding; Vector3, Vector2, Color3, CFrame, UDim2, BrickColor, Random, Enum; task.wait / spawn / delay / defer, wait, spawn, tick, os.time.</p><p><b>Differenze</b>: 1 stud = 1 blocco (il personaggio è alto 1,8). Ogni giocatore esegue lo script nel proprio browser (come un LocalScript): ciò che lo script crea non è condiviso con gli altri giocatori. I pezzi sciolti cadono solo fino al terreno o su un blocco. WalkSpeed 16 e JumpPower 50 corrispondono alla velocità e al salto normali.</p><p><b>Non disponibile</b>: DataStores, HTTP reale, modelli e MeshParts di Roblox, animazioni, Terrain, fisica completa, Raycast, script su più file (require).</p>",
    cant_self: "Non puoi aggiungere te stesso",
    no_my_games: "Non hai ancora creato nessun gioco.",
    ed_script_help: "JavaScript eseguito in isolamento in un Worker. Eventi: on(\"join\"), on(\"chat\"), on(\"command\"), on(\"tick\"). Azioni: say, title, teleport, setSpeed, setJump, setGravity, emote, sky, sound.",
