    top_times: "Najlepsze czasy",
    your_rank: "Twoje miejsce: {n}",
    blocked_none: "Nikogo nie zablokowałeś.",
    ed_script_help_lua: "Lua w stylu Roblox (w izolacji): Instance.new(\"Part\"), workspace, game:GetService(\"Players\" / \"TweenService\" / \"RunService\" / \"UserInputService\" / \"Lighting\" / \"Debris\" / \"CollectionService\"), task.wait / task.spawn, zdarzenia z :Connect, Touched, ClickDetector, ProximityPrompt, ScreenGui / TextLabel / TextButton, leaderstats. Działają też on(\"join\"), command(\"name\", fn), game.say... 1 stud = 1 blok.",
    ed_api_title: "Opis API (Roblox)",
    ed_api: "<p><b>Obsługiwane</b>: Instance.new / Clone / Destroy / FindFirstChild / WaitForChild / GetChildren / SetAttribute; Part (Position, Size, Color, Material, Shape, Transparency, Anchored, CanCollide, CFrame, Touched), PointLight, ClickDetector.MouseClick, ProximityPrompt.Triggered, SpawnLocation, Model:MoveTo; Players (LocalPlayer, PlayerAdded, CharacterAdded, Chatted, leaderstats), Humanoid (WalkSpeed, JumpPower, Health, Died); Workspace.Gravity; Lighting.ClockTime; TweenService:Create + TweenInfo + Enum.EasingStyle; RunService.Heartbeat / RenderStepped; UserInputService.InputBegan / IsKeyDown; ContextActionService:BindAction; Debris:AddItem; CollectionService; HttpService:JSONEncode / JSONDecode / GenerateGUID; BindableEvent; RemoteEvent (lokalny); obiekty Value; ScreenGui, Frame, TextLabel, TextButton, UICorner, UIStroke, UIListLayout, UIPadding; Vector3, Vector2, Color3, CFrame, UDim2, BrickColor, Random, Enum; task.wait / spawn / delay / defer, wait, spawn, tick, os.time.</p><p><b>Różnice</b>: 1 stud = 1 blok (postać ma 1,8 wysokości). Każdy gracz uruchamia skrypt we własnej przeglądarce (jak LocalScript): to, co skrypt tworzy, nie jest współdzielone z innymi graczami. Luźne elementy spadają tylko na podłoże lub na blok. WalkSpeed 16 i JumpPower 50 odpowiadają zwykłej prędkości i skokowi.</p><p><b>Niedostępne</b>: DataStores, prawdziwe HTTP, modele i MeshParts z Roblox, animacje, Terrain, pełna fizyka, Raycast, skrypty z wielu plików (require).</p>",
    cant_self: "Nie możesz dodać samego siebie",
    no_my_games: "Nie stworzyłeś jeszcze żadnej gry.",
    ed_script_help: "JavaScript uruchamiany w izolacji w Workerze. Zdarzenia: on(\"join\"), on(\"chat\"), on(\"command\"), on(\"tick\"). Akcje: say, title, teleport, setSpeed, setJump, setGravity, emote, sky, sound.",
