    blocked_none: "Вы никого не заблокировали.",
    ed_script_help_lua: "Lua в стиле Roblox (в изоляции): Instance.new(\"Part\"), workspace, game:GetService(\"Players\" / \"TweenService\" / \"RunService\" / \"UserInputService\" / \"Lighting\" / \"Debris\" / \"CollectionService\"), task.wait / task.spawn, события через :Connect, Touched, ClickDetector, ProximityPrompt, ScreenGui / TextLabel / TextButton, leaderstats. Также работают on(\"join\"), command(\"name\", fn), game.say... 1 stud = 1 блок.",
    ed_api_title: "Справочник API (Roblox)",
    ed_api: "<p><b>Поддерживается</b>: Instance.new / Clone / Destroy / FindFirstChild / WaitForChild / GetChildren / SetAttribute; Part (Position, Size, Color, Material, Shape, Transparency, Anchored, CanCollide, CFrame, Touched), PointLight, ClickDetector.MouseClick, ProximityPrompt.Triggered, SpawnLocation, Model:MoveTo; Players (LocalPlayer, PlayerAdded, CharacterAdded, Chatted, leaderstats), Humanoid (WalkSpeed, JumpPower, Health, Died); Workspace.Gravity; Lighting.ClockTime; TweenService:Create + TweenInfo + Enum.EasingStyle; RunService.Heartbeat / RenderStepped; UserInputService.InputBegan / IsKeyDown; ContextActionService:BindAction; Debris:AddItem; CollectionService; HttpService:JSONEncode / JSONDecode / GenerateGUID; BindableEvent; RemoteEvent (локальный); объекты Value; ScreenGui, Frame, TextLabel, TextButton, UICorner, UIStroke, UIListLayout, UIPadding; Vector3, Vector2, Color3, CFrame, UDim2, BrickColor, Random, Enum; task.wait / spawn / delay / defer, wait, spawn, tick, os.time.</p><p><b>Отличия</b>: 1 stud = 1 блок (персонаж высотой 1,8). Каждый игрок запускает скрипт в своём браузере (как LocalScript): то, что создаёт скрипт, не видно другим игрокам. Свободные детали падают только на землю или на блок. WalkSpeed 16 и JumpPower 50 соответствуют обычной скорости и прыжку.</p><p><b>Недоступно</b>: DataStores, настоящий HTTP, модели и MeshParts из Roblox, анимации, Terrain, полная физика, Raycast, многофайловые скрипты (require).</p>",
    cant_self: "Нельзя добавить самого себя",
    no_my_games: "Вы ещё не создали ни одной игры.",
    ed_script_help: "JavaScript, выполняемый в изоляции в Worker. События: on(\"join\"), on(\"chat\"), on(\"command\"), on(\"tick\"). Действия: say, title, teleport, setSpeed, setJump, setGravity, emote, sky, sound.",
