    ed_script_help_lua: "Roblox風のLua（サンドボックス）: Instance.new(\"Part\")、workspace、game:GetService(\"Players\" / \"TweenService\" / \"RunService\" / \"UserInputService\" / \"Lighting\" / \"Debris\" / \"CollectionService\")、task.wait / task.spawn、:Connectによるイベント、Touched、ClickDetector、ProximityPrompt、ScreenGui / TextLabel / TextButton、leaderstats。on(\"join\")、command(\"name\", fn)、game.say... も使えます。1スタッド＝1ブロックです。",
    ed_api_title: "APIリファレンス（Roblox）",
    ed_api: "<p><b>対応</b>: Instance.new / Clone / Destroy / FindFirstChild / WaitForChild / GetChildren / SetAttribute; Part (Position, Size, Color, Material, Shape, Transparency, Anchored, CanCollide, CFrame, Touched), PointLight, ClickDetector.MouseClick, ProximityPrompt.Triggered, SpawnLocation, Model:MoveTo; Players (LocalPlayer, PlayerAdded, CharacterAdded, Chatted, leaderstats), Humanoid (WalkSpeed, JumpPower, Health, Died); Workspace.Gravity; Lighting.ClockTime; TweenService:Create + TweenInfo + Enum.EasingStyle; RunService.Heartbeat / RenderStepped; UserInputService.InputBegan / IsKeyDown; ContextActionService:BindAction; Debris:AddItem; CollectionService; HttpService:JSONEncode / JSONDecode / GenerateGUID; BindableEvent; RemoteEvent（ローカル）; Valueオブジェクト; ScreenGui, Frame, TextLabel, TextButton, UICorner, UIStroke, UIListLayout, UIPadding; Vector3, Vector2, Color3, CFrame, UDim2, BrickColor, Random, Enum; task.wait / spawn / delay / defer, wait, spawn, tick, os.time。</p><p><b>違い</b>: 1スタッド＝1ブロックです（キャラクターの高さは1.8）。各プレイヤーが自分のブラウザでスクリプトを実行します（LocalScriptのように）。スクリプトが作ったものはほかのプレイヤーとは共有されません。置いただけのパーツは地面かブロックの上まで落ちるだけです。WalkSpeed 16とJumpPower 50が通常の速度とジャンプに相当します。</p><p><b>非対応</b>: DataStores、実際のHTTP、Robloxのモデルとメッシュパーツ、アニメーション、Terrain、完全な物理演算、Raycast、複数ファイルのスクリプト（require）。</p>",
