    blocked_none: "你没有屏蔽任何人。",
    ed_script_help_lua: "Roblox 风格的 Lua（沙盒运行）：Instance.new(\"Part\")、workspace、game:GetService(\"Players\" / \"TweenService\" / \"RunService\" / \"UserInputService\" / \"Lighting\" / \"Debris\" / \"CollectionService\")、task.wait / task.spawn、:Connect 事件、Touched、ClickDetector、ProximityPrompt、ScreenGui / TextLabel / TextButton、leaderstats。on(\"join\")、command(\"name\", fn)、game.say... 也可使用。1 stud = 1 个方块。",
    ed_api_title: "API 参考（Roblox）",
    ed_api: "<p><b>已支持</b>：Instance.new / Clone / Destroy / FindFirstChild / WaitForChild / GetChildren / SetAttribute；Part（Position、Size、Color、Material、Shape、Transparency、Anchored、CanCollide、CFrame、Touched）、PointLight、ClickDetector.MouseClick、ProximityPrompt.Triggered、SpawnLocation、Model:MoveTo；Players（LocalPlayer、PlayerAdded、CharacterAdded、Chatted、leaderstats）、Humanoid（WalkSpeed、JumpPower、Health、Died）；Workspace.Gravity；Lighting.ClockTime；TweenService:Create + TweenInfo + Enum.EasingStyle；RunService.Heartbeat / RenderStepped；UserInputService.InputBegan / IsKeyDown；ContextActionService:BindAction；Debris:AddItem；CollectionService；HttpService:JSONEncode / JSONDecode / GenerateGUID；BindableEvent；RemoteEvent（本地）；Value 对象；ScreenGui、Frame、TextLabel、TextButton、UICorner、UIStroke、UIListLayout、UIPadding；Vector3、Vector2、Color3、CFrame、UDim2、BrickColor、Random、Enum；task.wait / spawn / delay / defer、wait、spawn、tick、os.time。</p><p><b>差异</b>：1 stud = 1 个方块（角色高 1.8）。每位玩家在自己的浏览器中运行脚本（类似 LocalScript）：脚本创建的内容不会与其他玩家共享。松散的部件只会落到地面或方块上。WalkSpeed 16 和 JumpPower 50 对应正常的速度和跳跃。</p><p><b>不支持</b>：DataStores、真实的 HTTP、Roblox 模型和 MeshParts、动画、Terrain、完整物理、Raycast、多文件脚本（require）。</p>",
    cant_self: "你不能添加自己",
    no_my_games: "你还没有创建任何游戏。",
    ed_script_help: "在 Worker 中以沙盒方式运行的 JavaScript。事件：on(\"join\")、on(\"chat\")、on(\"command\")、on(\"tick\")。动作：say、title、teleport、setSpeed、setJump、setGravity、emote、sky、sound。",
