    blocked_none: "차단한 사람이 없습니다.",
    ed_script_help_lua: "Roblox 스타일 Lua (샌드박스): Instance.new(\"Part\"), workspace, game:GetService(\"Players\" / \"TweenService\" / \"RunService\" / \"UserInputService\" / \"Lighting\" / \"Debris\" / \"CollectionService\"), task.wait / task.spawn, :Connect 이벤트, Touched, ClickDetector, ProximityPrompt, ScreenGui / TextLabel / TextButton, leaderstats. on(\"join\"), command(\"name\", fn), game.say... 도 작동합니다. 1 stud = 1블록.",
    ed_api_title: "API 참조 (Roblox)",
    ed_api: "<p><b>지원</b>: Instance.new / Clone / Destroy / FindFirstChild / WaitForChild / GetChildren / SetAttribute; Part (Position, Size, Color, Material, Shape, Transparency, Anchored, CanCollide, CFrame, Touched), PointLight, ClickDetector.MouseClick, ProximityPrompt.Triggered, SpawnLocation, Model:MoveTo; Players (LocalPlayer, PlayerAdded, CharacterAdded, Chatted, leaderstats), Humanoid (WalkSpeed, JumpPower, Health, Died); Workspace.Gravity; Lighting.ClockTime; TweenService:Create + TweenInfo + Enum.EasingStyle; RunService.Heartbeat / RenderStepped; UserInputService.InputBegan / IsKeyDown; ContextActionService:BindAction; Debris:AddItem; CollectionService; HttpService:JSONEncode / JSONDecode / GenerateGUID; BindableEvent; RemoteEvent (로컬); Value 오브젝트; ScreenGui, Frame, TextLabel, TextButton, UICorner, UIStroke, UIListLayout, UIPadding; Vector3, Vector2, Color3, CFrame, UDim2, BrickColor, Random, Enum; task.wait / spawn / delay / defer, wait, spawn, tick, os.time.</p><p><b>차이점</b>: 1 stud = 1블록입니다(캐릭터 키는 1.8). 각 플레이어가 자기 브라우저에서 스크립트를 실행합니다(LocalScript처럼). 스크립트가 만든 것은 다른 플레이어와 공유되지 않습니다. 놓기만 한 파트는 바닥이나 블록 위까지만 떨어집니다. WalkSpeed 16과 JumpPower 50이 보통의 속도와 점프에 해당합니다.</p><p><b>지원하지 않음</b>: DataStores, 실제 HTTP, Roblox 모델과 MeshParts, 애니메이션, Terrain, 완전한 물리, Raycast, 여러 파일 스크립트(require).</p>",
    cant_self: "자기 자신은 추가할 수 없습니다",
